import{_ as a,o,c as i,a0 as t}from"./chunks/framework.CUwGMaR-.js";const m=JSON.parse('{"title":"CHANGELOG","description":"","frontmatter":{"outline":[2,3]},"headers":[],"relativePath":"en/changelog.md","filePath":"en/changelog.md"}'),n={name:"en/changelog.md"};function d(r,e,l,s,c,h){return o(),i("div",null,[...e[0]||(e[0]=[t('<h1 id="changelog" tabindex="-1">CHANGELOG <a class="header-anchor" href="#changelog" aria-label="Permalink to &quot;CHANGELOG&quot;">​</a></h1><h2 id="_1-2-0-2026-11-19" tabindex="-1">[1.2.0] - 2026-11-19 <a class="header-anchor" href="#_1-2-0-2026-11-19" aria-label="Permalink to &quot;[1.2.0] - 2026-11-19&quot;">​</a></h2><h3 id="✨-added" tabindex="-1">✨ Added <a class="header-anchor" href="#✨-added" aria-label="Permalink to &quot;✨ Added&quot;">​</a></h3><ul><li><code>migrate()</code> and <code>plan_migration()</code> (sync and async; <code>plan_migration()</code> also takes <code>fill=</code>) bring an existing table in line with a changed model. Added columns run directly; dropping columns, changing types, or adding NOT NULL need <code>allow_destructive=True</code>. Each migration runs in one transaction and rolls back on failure.</li><li>Table rebuilds check that copied values fit the new column types before swapping tables, and keep <code>rowid</code> values for tables without an integer primary key.</li><li><code>__nyan_renames__ = {&quot;new&quot;: &quot;old&quot;}</code> on a model renames columns without losing values. <code>fill={&quot;column&quot;: value_or_function(row)}</code> supplies values for new or converted columns. Both are ignored once the column is migrated, so they can stay in start-up code.</li><li><code>register(model, on_mismatch=&quot;migrate&quot;)</code> runs <code>migrate()</code> before registering. The default <code>&quot;error&quot;</code> keeps the strict behavior.</li><li><code>backup=True</code> (or a path) copies the database file with <code>VACUUM INTO</code> before a migration changes anything. Off by default.</li><li><code>MigrationError</code>, <code>MigrationPlan</code>, and <code>MigrationStep</code> are exported.</li></ul><h3 id="🔧-changed" tabindex="-1">🔧 Changed <a class="header-anchor" href="#🔧-changed" aria-label="Permalink to &quot;🔧 Changed&quot;">​</a></h3><ul><li><code>SchemaMismatchError</code> messages now point to <code>plan_migration()</code> and <code>migrate()</code>. <code>register()</code> itself still never edits an existing table.</li></ul><hr><h2 id="_1-1-7-2026-11-17" tabindex="-1">[1.1.7] - 2026-11-17 <a class="header-anchor" href="#_1-1-7-2026-11-17" aria-label="Permalink to &quot;[1.1.7] - 2026-11-17&quot;">​</a></h2><h3 id="🚀-performance" tabindex="-1">🚀 Performance <a class="header-anchor" href="#🚀-performance" aria-label="Permalink to &quot;🚀 Performance&quot;">​</a></h3><ul><li>Reused INSERT statements and field encoders for single-row inserts. Sync inserts use SQLite&#39;s implicit transaction unless a transaction is already open.</li><li>In five local Python 3.12 benchmark sets, the median time reduction for 10,000 sync inserts into a WAL database was 30.4% on APSW and 24.2% on sqlite3.</li></ul><h3 id="🐞-fixed" tabindex="-1">🐞 Fixed <a class="header-anchor" href="#🐞-fixed" aria-label="Permalink to &quot;🐞 Fixed&quot;">​</a></h3><ul><li>Finished async transaction rollback under repeated cancellation and kept committed registrations when cancellation arrived during a successful commit.</li><li>Updated model registration only when the containing transaction commits and rejected concurrent table-name collisions.</li><li>Preserved the original exception when SQLite had already rolled back the transaction.</li><li>Applied Pydantic serializers and field exclusions consistently to single and bulk inserts.</li></ul><h3 id="🧪-tests-and-ci" tabindex="-1">🧪 Tests and CI <a class="header-anchor" href="#🧪-tests-and-ci" aria-label="Permalink to &quot;🧪 Tests and CI&quot;">​</a></h3><ul><li>Added transaction, registration, and bulk serialization regression tests.</li><li>Ran Python 3.9 CI on Ubuntu 24.04, which provides supported Python 3.9 builds.</li></ul><hr><h2 id="_1-1-6-2026-09-27" tabindex="-1">[1.1.6] - 2026-09-27 <a class="header-anchor" href="#_1-1-6-2026-09-27" aria-label="Permalink to &quot;[1.1.6] - 2026-09-27&quot;">​</a></h2><h3 id="🚀-performance-1" tabindex="-1">🚀 Performance <a class="header-anchor" href="#🚀-performance-1" aria-label="Permalink to &quot;🚀 Performance&quot;">​</a></h3><ul><li>Streamed <code>insert_many()</code> rows to SQLite within the existing transaction, and prepared field serializers and INSERT SQL when registering a model. SQLite&#39;s parameter limit applies to each execution of the single-row INSERT.</li><li>Decoded SQLite tuples directly into the dictionary validated by Pydantic. Normal JSON values use Pydantic Core&#39;s parser, with a fallback for values it rejects. Sync and async bulk conversion retain Pydantic validation; the async path runs bulk CPU work off the event loop.</li><li>Reused prepared statements when callers supply the same keyword filters in different orders. Added optional <code>statement_cache_size</code> to both constructors; the backend default is unchanged when omitted.</li><li>For ordinary models, used Pydantic Core&#39;s validator to reduce per-row construction overhead. Models with custom construction, model validators, or other incompatible features keep the constructor path.</li></ul><h3 id="🧪-benchmarks-and-tests" tabindex="-1">🧪 Benchmarks and tests <a class="header-anchor" href="#🧪-benchmarks-and-tests" aria-label="Permalink to &quot;🧪 Benchmarks and tests&quot;">​</a></h3><ul><li>Restored sync and async benchmark suites and the result parser; benchmark workflow failures are no longer masked.</li><li>Added regression tests for large inserts and rollback, column order, Pydantic validators, asynchronous conversion, JSON edge cases, SQL parameter binding, and cache configuration.</li><li>In local Python 3.12 in-memory runs, the later model-read improvement changed the median for 1,000 rows from 1.974 to 1.671 ms (sync) and 3.044 to 2.626 ms (async). Reordering six keyword filters across 480 sync queries changed 8.964 to 4.955 ms. Async timings vary; fixed-order six-filter queries have a small overhead.</li></ul><hr><h2 id="_1-1-5-2026-09-26" tabindex="-1">[1.1.5] - 2026-09-26 <a class="header-anchor" href="#_1-1-5-2026-09-26" aria-label="Permalink to &quot;[1.1.5] - 2026-09-26&quot;">​</a></h2><h3 id="🚀-performance-2" tabindex="-1">🚀 Performance <a class="header-anchor" href="#🚀-performance-2" aria-label="Permalink to &quot;🚀 Performance&quot;">​</a></h3><ul><li>Prepare field-specific decoders and the update validation route at registration. In a local paired conversion benchmark on 20,000 rows with scalar, datetime, and list fields, median time fell from 0.194 to 0.166 seconds.</li><li>Cached type inspection while decoding rows. In a local 10,000-row benchmark, median query time fell from 0.098 to 0.068 seconds (sync) and from 0.108 to 0.074 seconds (async).</li><li>Bound <code>LIMIT</code> and <code>OFFSET</code> as SQL parameters. In a local 1,000-query pagination benchmark, median time fell from 0.0341 to 0.0315 seconds.</li><li>Removed unused JSON conversion in <code>__in</code> filters. Building 500 filters of 1,000 integers fell from 0.138 to 0.091 seconds locally.</li></ul><h3 id="🐞-fixed-1" tabindex="-1">🐞 Fixed <a class="header-anchor" href="#🐞-fixed-1" aria-label="Permalink to &quot;🐞 Fixed&quot;">​</a></h3><ul><li>Updated documentation dependencies to address known vulnerabilities and limited the optional <code>cryptography</code> dependency to a fixed release on Python 3.10+.</li><li>Protected in-flight SQLite calls after async cancellation and rolled back open transactions; sync transactions also roll back on interruptions.</li><li><code>update()</code> now validates changed values, with affected-row validation for models that have custom validators or configuration.</li><li><code>register()</code> now raises <code>SchemaMismatchError</code> when an existing table&#39;s columns, types, primary key, nullability, or FTS searchable columns differ from the model.</li><li>Adding full-text search to an existing table now indexes existing rows immediately.</li></ul><h3 id="📚-docs" tabindex="-1">📚 Docs <a class="header-anchor" href="#📚-docs" aria-label="Permalink to &quot;📚 Docs&quot;">​</a></h3><ul><li>Corrected the error and exception guides, backup example, projection advice, batched async reads, and continuation-based pagination.</li></ul><h3 id="⚠️-compatibility" tabindex="-1">⚠️ Compatibility <a class="header-anchor" href="#⚠️-compatibility" aria-label="Permalink to &quot;⚠️ Compatibility&quot;">​</a></h3><ul><li>On Python 3.9, the <code>encryption</code>, <code>all</code>, and <code>dev</code> extras no longer install <code>cryptography</code>. Core Python 3.9 support remains.</li><li>Invalid partial updates now raise Pydantic <code>ValidationError</code>. Incompatible existing tables raise <code>SchemaMismatchError</code> on registration; migrate them explicitly.</li></ul><hr><h2 id="_1-1-4-2026-06-22" tabindex="-1">[1.1.4] - 2026-06-22 <a class="header-anchor" href="#_1-1-4-2026-06-22" aria-label="Permalink to &quot;[1.1.4] - 2026-06-22&quot;">​</a></h2><h3 id="🐞-fixed-2" tabindex="-1">🐞 Fixed <a class="header-anchor" href="#🐞-fixed-2" aria-label="Permalink to &quot;🐞 Fixed&quot;">​</a></h3><ul><li>Validated all generated SQLite identifiers and rejected unknown composite-index fields before constructing schema SQL.</li><li>Hardened string filters so unsupported raw SQL fragments now raise <code>QueryValidationError</code> instead of being passed through to SQL.</li><li>Aligned async query validation with the sync implementation, including unknown-field checks and model-aware filter value serialization.</li><li>Fixed async filtering for <code>date</code>, <code>datetime</code>, <code>list</code>, and <code>dict</code> values.</li><li>Fixed <code>__in</code> handling so normal lists/tuples/sets work consistently and empty collections return no rows.</li><li>Fixed offset-only pagination by emitting SQLite&#39;s required unlimited <code>LIMIT</code> clause.</li><li>Tightened <code>limit</code> / <code>offset</code> validation to reject negative values, floats, booleans, and strings.</li><li>Added a clear <code>TypeError</code> when <code>insert_many()</code> receives mixed model types.</li><li>Serialized reads and connection shutdown with the existing locks so <code>close()</code> cannot race active queries.</li><li>Protected <code>vacuum()</code> and async <code>execute_raw()</code> with the existing connection locks.</li></ul><h3 id="🧪-tests" tabindex="-1">🧪 Tests <a class="header-anchor" href="#🧪-tests" aria-label="Permalink to &quot;🧪 Tests&quot;">​</a></h3><ul><li>Added regression tests for unsafe string filters, async field validation, serialized filter values, <code>__in</code>, offset-only pagination, strict pagination types, and mixed-model bulk inserts.</li></ul><h3 id="📚-docs-1" tabindex="-1">📚 Docs <a class="header-anchor" href="#📚-docs-1" aria-label="Permalink to &quot;📚 Docs&quot;">​</a></h3><ul><li>Added an APSW full-access implementation plan.</li></ul><h3 id="⚠️-compatibility-1" tabindex="-1">⚠️ Compatibility <a class="header-anchor" href="#⚠️-compatibility-1" aria-label="Permalink to &quot;⚠️ Compatibility&quot;">​</a></h3><ul><li>String filters now support only simple comparisons such as <code>&quot;age &gt; 10&quot;</code> or <code>&quot;name = &#39;Alice&#39;&quot;</code>. Use keyword filters such as <code>age__gte=10</code> for advanced filtering.</li><li>Python 3.9 remains supported for the core package. Some optional and development dependencies cannot provide their latest security-fixed wheels on Python 3.9; use Python 3.10+ for the <code>speed</code>, <code>encryption</code>, and <code>dev</code> extras when processing untrusted input.</li></ul><hr><h2 id="_1-1-1-2026-05-16" tabindex="-1">[1.1.1] - 2026-05-16 <a class="header-anchor" href="#_1-1-1-2026-05-16" aria-label="Permalink to &quot;[1.1.1] - 2026-05-16&quot;">​</a></h2><h3 id="🚀-added" tabindex="-1">🚀 Added <a class="header-anchor" href="#🚀-added" aria-label="Permalink to &quot;🚀 Added&quot;">​</a></h3><ul><li><strong>Explicit Transactions</strong>: Added <code>atomic()</code> context manager to <code>NyanSQLite</code> and <code>async with atomic()</code> to <code>NyanSQLiteAIO</code> for manual transaction control.</li><li><strong>Nested Transactions</strong>: Added support for nested <code>atomic()</code> blocks.</li></ul><h3 id="🔄-changed" tabindex="-1">🔄 Changed <a class="header-anchor" href="#🔄-changed" aria-label="Permalink to &quot;🔄 Changed&quot;">​</a></h3><ul><li><strong>Thread Safety</strong>: Improved thread safety by switching to <code>threading.RLock</code> in <code>NyanSQLite</code>.</li><li><strong>Async Safety</strong>: Implemented re-entrant async lock in <code>NyanSQLiteAIO</code> to prevent deadlocks when using <code>atomic()</code>.</li></ul><hr><h2 id="_1-1-0-2026-05-16" tabindex="-1">[1.1.0] - 2026-05-16 <a class="header-anchor" href="#_1-1-0-2026-05-16" aria-label="Permalink to &quot;[1.1.0] - 2026-05-16&quot;">​</a></h2><h3 id="🚀-added-1" tabindex="-1">🚀 Added <a class="header-anchor" href="#🚀-added-1" aria-label="Permalink to &quot;🚀 Added&quot;">​</a></h3><ul><li><strong>Asynchronous Support</strong>: Full support for <code>asyncio</code> via <code>NyanSQLiteAIO</code> class.</li><li><strong>Improved Performance</strong>: Optimized read operations by minimizing thread context switching and processing rows efficiently in <code>asyncio.to_thread</code>.</li><li><strong>Documentation Updates</strong>: Added English and Japanese documentation for asynchronous usage.</li></ul><h3 id="🔄-changed-1" tabindex="-1">🔄 Changed <a class="header-anchor" href="#🔄-changed-1" aria-label="Permalink to &quot;🔄 Changed&quot;">​</a></h3><ul><li>Internal optimization for <code>query</code>, <code>select</code>, and <code>search</code> methods in <code>NyanSQLiteAIO</code>.</li><li>Optimized read operations in synchronous <code>NyanSQLite</code> class by minimizing lock duration.</li></ul><hr><h2 id="_1-0-1-2026-05-15" tabindex="-1">[1.0.1] - 2026-05-15 <a class="header-anchor" href="#_1-0-1-2026-05-15" aria-label="Permalink to &quot;[1.0.1] - 2026-05-15&quot;">​</a></h2><h3 id="🐞-fixed-3" tabindex="-1">🐞 Fixed <a class="header-anchor" href="#🐞-fixed-3" aria-label="Permalink to &quot;🐞 Fixed&quot;">​</a></h3><ul><li>Minor bug fixes and performance improvements.</li></ul><hr><h2 id="_1-0-0-2026-05-15" tabindex="-1">[1.0.0] - 2026-05-15 <a class="header-anchor" href="#_1-0-0-2026-05-15" aria-label="Permalink to &quot;[1.0.0] - 2026-05-15&quot;">​</a></h2><h3 id="🚀-added-2" tabindex="-1">🚀 Added <a class="header-anchor" href="#🚀-added-2" aria-label="Permalink to &quot;🚀 Added&quot;">​</a></h3><ul><li><strong>Pydantic v2 support</strong>: Models can be used directly as database schemas.</li><li><strong>Django-like Query Syntax</strong>: Support for intuitive filtering such as <code>__gte</code>, <code>__in</code>, <code>__like</code>, etc.</li><li><strong>FTS5 Full-Text Search</strong>: Fast full-text search capabilities using SQLite&#39;s FTS5 extension.</li><li><strong>Automatic Index Management</strong>: B-tree indexes are automatically created using <code>Indexed[T]</code> and <code>UniqueIndexed[T]</code> annotations.</li><li><strong>Composite Indexes</strong>: Support for <code>CompositeIndex</code> via Pydantic&#39;s <code>Field</code> extra metadata.</li><li><strong>Transparent Type Handling</strong>: Automatically handles complex types like <code>dict</code> and <code>list</code> by serializing them to JSON.</li><li><strong>WAL Mode Support</strong>: Write-Ahead Logging is enabled by default for better performance and concurrency.</li><li><strong>Context Manager Support</strong>: <code>NyanSQLite</code> can be used as a context manager for automatic connection closing.</li></ul><h3 id="🔄-changed-2" tabindex="-1">🔄 Changed <a class="header-anchor" href="#🔄-changed-2" aria-label="Permalink to &quot;🔄 Changed&quot;">​</a></h3><ul><li>Initial public release of NyanSQLite.</li></ul><hr>',63)])])}const g=a(n,[["render",d]]);export{m as __pageData,g as default};
